CREATE TABLE "ThreadConclusion" ("id" TEXT NOT NULL PRIMARY KEY, "threadId" TEXT NOT NULL, "roomId" TEXT NOT NULL, "createdBy" TEXT NOT NULL, "summary" TEXT NOT NULL, "sources" JSONB NOT NULL, "model" TEXT, "confirmedAt" TIMESTAMP(3), "deletedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ThreadConclusion_threadId_fkey" FOREIGN KEY ("threadId") REFERENCES "Thread"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ThreadConclusion_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "ThreadConclusion_threadId_createdBy_key" ON "ThreadConclusion"("threadId", "createdBy");
